# Lambda 아키텍처: 컨테이너 이미지 + 함수 URL
# 이미지에 AWS Lambda Web Adapter가 포함되어 있어 일반 웹앱이 동작함
# 입력: name, image_uri, container_port, size, env, health_path
# 출력: endpoint, health_url, resource_id

terraform {
  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
  }
}

variable "name"           { type = string }
variable "image_uri"      { type = string }
variable "container_port" { type = number }
variable "size"           { type = string }
variable "env"            { type = map(string) }
variable "health_path"    { type = string }

locals {
  # size별 메모리 크기 (MB). micro=512, small=1024, medium=2048
  memory = {
    micro  = 512
    small  = 1024
    medium = 2048
  }
}

# Lambda 실행 역할 — 로그 쓰기 권한만 부여
# IAM 이름 64자 제한으로 name_prefix는 "-" 포함 38자 이하
resource "aws_iam_role" "app" {
  name_prefix = "${substr(var.name, 0, 37)}-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

# 로그 쓰기만 허용하는 AWS 관리형 정책 연결
resource "aws_iam_role_policy_attachment" "logs" {
  role       = aws_iam_role.app.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# Lambda 함수 — 컨테이너 이미지 방식, micro=512MB, 타임아웃 30초
resource "aws_lambda_function" "app" {
  function_name = var.name
  role          = aws_iam_role.app.arn
  package_type  = "Image"
  image_uri     = var.image_uri
  architectures = ["x86_64"]
  timeout       = 30
  memory_size   = local.memory[var.size]

  environment {
    variables = merge(var.env, {
      PORT         = tostring(var.container_port)
      AWS_LWA_PORT = tostring(var.container_port) # Lambda Web Adapter가 앱으로 넘길 포트
    })
  }

  depends_on = [aws_iam_role_policy_attachment.logs]
}

# 인증 없는 퍼블릭 함수 URL 생성
resource "aws_lambda_function_url" "app" {
  function_name      = aws_lambda_function.app.function_name
  authorization_type = "NONE"
}

# 함수 URL 공개 호출 허용 (InvokeFunctionUrl)
# 2025-10부터 InvokeFunctionUrl + InvokeFunction 둘 다 필요, 하나라도 빠지면 403
resource "aws_lambda_permission" "public_url" {
  statement_id           = "AllowPublicFunctionUrl"
  action                 = "lambda:InvokeFunctionUrl"
  function_name          = aws_lambda_function.app.function_name
  principal              = "*"
  function_url_auth_type = "NONE"
}

# 함수 URL 경유 호출만 허용 (직접 Invoke API는 차단)
resource "aws_lambda_permission" "public_invoke" {
  statement_id             = "AllowPublicInvokeViaFunctionUrl"
  action                   = "lambda:InvokeFunction"
  function_name            = aws_lambda_function.app.function_name
  principal                = "*"
  invoked_via_function_url = true
}

# 함수 URL (끝 슬래시 제거)
output "endpoint" {
  value = trimsuffix(aws_lambda_function_url.app.function_url, "/")
}

# 헬스체크 URL — health_path = "/"
output "health_url" {
  value = "${trimsuffix(aws_lambda_function_url.app.function_url, "/")}${var.health_path}"
}

# Lambda 함수 ARN
output "resource_id" {
  value = aws_lambda_function.app.arn
}

# GCP Cloud Run 아키텍처: 컨테이너 1개를 서버리스로 실행 + 공개 URL
# 공통 입력: name, image_uri, container_port, size, env, health_path
# 공통 출력: endpoint, health_url, resource_id
# 이미지는 같은 프로젝트의 Artifact Registry 에 있어야 한다

terraform {
  required_providers {
    google = {
      source = "hashicorp/google"
    }
  }
}

variable "name"           { type = string }
variable "image_uri"      { type = string }
variable "container_port" { type = number }
variable "size"           { type = string }
variable "env"            { type = map(string) }
variable "health_path"    { type = string }

locals {
  # size → 메모리 매핑 (micro=512Mi, small=1Gi, medium=2Gi)
  memory = {
    micro  = "512Mi"
    small  = "1Gi"
    medium = "2Gi"
  }

  # 서비스 계정 ID: 6~30자, 끝 하이픈 제거
  account_id = replace(substr(replace(var.name, "pawploy-", "pp-"), 0, 30), "/-+$/", "")
}

# 앱 전용 서비스 계정: 역할 없음
# 기본 Compute 서비스 계정(편집자 권한) 사용을 막기 위해 반드시 지정한다
resource "google_service_account" "app" {
  account_id   = local.account_id
  display_name = "Pawploy ${var.name}"
}

# 현재 프로젝트·리전 정보 (루트 main.tf 에서 워커가 설정)
data "google_client_config" "current" {}

resource "google_cloud_run_v2_service" "app" {
  name     = var.name
  location = data.google_client_config.current.region
  ingress  = "INGRESS_TRAFFIC_ALL"

  # false 로 설정해야 terraform destroy 가 정상 동작한다
  deletion_protection = false

  template {
    service_account = google_service_account.app.email
    timeout         = "60s"

    scaling {
      min_instance_count = 0
      max_instance_count = 1 # 악용·과금 방지
    }

    containers {
      image = var.image_uri

      ports {
        # Cloud Run 이 PORT 환경변수를 자동 주입하므로 직접 넣으면 거부됨
        container_port = var.container_port
      }

      resources {
        limits = {
          cpu    = "1"
          memory = local.memory[var.size]
        }
        cpu_idle = true # 요청 없을 때 CPU 과금 안 함
      }

      # 헬스체크 경로로 시작 프로브 설정
      startup_probe {
        http_get {
          path = var.health_path
        }
        initial_delay_seconds = 5
        period_seconds        = 10
        failure_threshold     = 3
      }

      dynamic "env" {
        for_each = var.env
        content {
          name  = env.key
          value = env.value
        }
      }
    }
  }
}

# 인증 없이 누구나 접속 (테스트 환경)
# 조직 정책이 allUsers 를 막으면 여기서 실패한다
resource "google_cloud_run_v2_service_iam_member" "public" {
  name     = google_cloud_run_v2_service.app.name
  location = google_cloud_run_v2_service.app.location
  role     = "roles/run.invoker"
  member   = "allUsers"
}

output "endpoint" {
  value = google_cloud_run_v2_service.app.uri
}

output "health_url" {
  value = "${google_cloud_run_v2_service.app.uri}${var.health_path}"
}

output "resource_id" {
  value = google_cloud_run_v2_service.app.id
}
